<script setup>
import { Head, Link } from '@inertiajs/vue3';
import { computed } from 'vue';
import { postBySlug } from '../data/staticBlogPosts.js';
const props=defineProps({slug:{type:String,required:true}}); const post=computed(()=>postBySlug(props.slug));
const schema=computed(()=>post.value?({'@context':'https://schema.org','@type':'Article',headline:post.value.title,description:post.value.metaDescription,datePublished:'2026-11-25',author:{'@type':'Organization',name:'Infinicode System'},publisher:{'@type':'Organization',name:'Infinicode System'}}):{});
</script>
<template><Head v-if="post" :title="post.metaTitle"><meta head-key="description" name="description" :content="post.metaDescription"/><meta head-key="og:title" property="og:title" :content="post.title"/><meta head-key="og:description" property="og:description" :content="post.metaDescription"/><meta head-key="og:type" property="og:type" content="article"/><script type="application/ld+json">{{JSON.stringify(schema)}}</script></Head><main v-if="post" class="static-page"><section class="static-hero static-hero--article"><div class="static-shell"><div class="eyebrow">{{post.category}} · {{post.readTime}}</div><h1>{{post.title}}</h1><p class="hero-copy">{{post.excerpt}}</p><div class="hero-meta">{{post.publishedAt}} · By Infinicode System</div></div></section><article class="static-shell article-layout"><div class="article-main"><p class="article-intro">{{post.intro}}</p><div v-for="section in post.sections" :key="section.heading" class="article-section"><h2>{{section.heading}}</h2><p>{{section.body}}</p></div><div class="article-cta"><span class="eyebrow">Build the next workflow</span><h2>Turn a complex process into software your team can use.</h2><Link href="/consultation" class="static-button">Start a consultation</Link></div></div><aside class="article-aside"><div class="aside-card"><strong>Target topic</strong><span>{{post.keyword}}</span></div><div class="aside-card"><strong>Related service</strong><Link href="/services/custom-software">Custom software development</Link></div><div class="aside-card"><strong>Explore more</strong><Link href="/blog">All insights</Link></div></aside></article></main></template>
